  async function resolveBoxInput(input,note,{defectOnly=false,silent=false}={}){const scan=normalizeStorageInput(input),raw=scan.value,layoutSuffix=scan.corrected?' · раскладка РУ→EN исправлена':'';if(!raw){delete input.dataset.pvzInvalid;if(note){note.textContent='Русская раскладка сканера исправляется автоматически.';note.className='pvz-scan-note';}return null;}let box=containerByScan(raw,{defectOnly});if(!box){await ensurePvzContext(true);box=containerByScan(raw,{defectOnly});}if(!defectOnly&&matchingDefectBox(raw)){input.dataset.pvzInvalid='defect';if(note){note.textContent='Это короб брака. Возврат в MAIN нельзя принимать в него.'+layoutSuffix;note.className='pvz-scan-note bad';}if(!silent)toast('Короб брака нельзя использовать для обычного возврата',true);return null;}if(!box){delete input.dataset.pvzInvalid;if(note){note.textContent=(defectOnly?'Короб брака не найден. Можно создать его с этим точным названием кнопкой рядом.':'Короб пока не найден локально; сервер проверит его при приёмке.')+layoutSuffix;note.className='pvz-scan-note '+(defectOnly?'bad':'');}if(defectOnly&&!silent)toast('Короб брака не найден',true);return null;}delete input.dataset.pvzInvalid;const publicName=friendlyContainer(box);input.value=publicName;if(note){note.textContent=`Короб: ${publicName}${layoutSuffix}`;note.className='pvz-scan-note good';}return box;}
  async function createDefectBoxAndPrint(defect,customName=''){if(!state.clientId||!state.warehouseId)throw new Error('Сначала выберите клиента и склад');const custom=normalizeStorageKeyboardValue(customName);const ps=typeof wbPrintSettings==='function'?wbPrintSettings():{mode:'browser',station:'PACK-01'},payload={...ctx(),performed_by:defectWorker()||worker()||actor(),print_station:ps.mode==='agent'?ps.station:null,custom_name:custom||null};const r=await api('/defect-storage/boxes',{method:'POST',body:JSON.stringify(payload),timeoutMs:15000});defect.container_code.value=r.name||r.barcode;const note=q('#pvzDefectContainerSelected');if(note){note.textContent=`${r.created===false?'Выбран существующий':'Создан'} короб: ${r.name}`+(r.print_station?` · отправлен в ${r.print_station}`:'');note.className='pvz-scan-note good';}if(ps.mode!=='agent'){const blob=await apiBlob(`/defect-storage/boxes/${encodeURIComponent(r.box_id)}/label.pdf?`+new URLSearchParams(ctx()),{timeoutMs:15000});printBlob(blob,`${r.name||'BRAK'}_58x40.pdf`);}await loadContextData({quiet:true,force:true}).catch(()=>{});if(!containerByScan(r.name,{defectOnly:true})&&!containerByScan(r.barcode,{defectOnly:true}))state.containers.push({id:r.box_id,name:r.name,barcode:r.barcode,container_type:'DEFECT_BOX',status:'DEFECT_ACTIVE'});return r;}
  function safePhoto(value){if(value&&typeof value==='object')value=value.big||value.c516x688||value.c246x328||value.square||'';const s=String(value||'').trim();return /^https?:\/\//i.test(s)?s:'';}
  function clearProductPreview(){currentProductPreview=null;const preview=q('#pvzProductPreview');if(!preview)return;preview.hidden=true;preview.innerHTML='';preview.className='pvz-full pvz-product-preview no-photo';preview.removeAttribute('tabindex');preview.removeAttribute('role');preview.removeAttribute('title');}
  function renderProductPreview(d){const preview=q('#pvzProductPreview');if(!preview)return;currentProductPreview=d||null;const photo=safePhoto(d?.photo||d?.photos?.[0]),title=d?.name||d?.title||d?.local_name||d?.article||'Товар',article=d?.article||d?.vendor_code||'—',size=d?.size||'—',brand=d?.brand||'',subject=d?.subject_name||'',canOpen=Boolean(d?.product_id||d?.article||d?.barcode);preview.className=`pvz-full pvz-product-preview ${photo?'has-photo':'no-photo'}${canOpen?' is-clickable':''}`;preview.innerHTML=`${photo?`<div class="pvz-product-photo"><img alt="${esc(title)}"></div>`:''}<div class="pvz-product-info"><div class="pvz-product-kicker">Локальная база товаров</div><div class="pvz-product-title">${esc(title)}</div><div class="pvz-product-main">${esc(article)} · ${esc(size)}</div><div class="pvz-small">ШК ${esc(d?.barcode||'—')}</div><div class="pvz-product-meta">${brand?`<span class="pvz-product-chip">${esc(brand)}</span>`:''}${subject?`<span class="pvz-product-chip">${esc(subject)}</span>`:''}${d?.enriched?'<span class="pvz-product-chip">карточка дополнена локальными данными</span>':'<span class="pvz-product-chip">локальная карточка</span>'}</div>${d?.warning?`<div class="pvz-product-note">${esc(d.warning)}</div>`:''}${canOpen?'<div class="pvz-product-open-hint">Открыть карточку товара →</div>':''}</div>`;preview.hidden=false;if(canOpen){preview.tabIndex=0;preview.setAttribute('role','button');preview.title='Открыть карточку товара';}else{preview.removeAttribute('tabindex');preview.removeAttribute('role');preview.removeAttribute('title');}if(photo){const img=q('img',preview);if(img){img.addEventListener('error',()=>{q('.pvz-product-photo',preview)?.remove();preview.classList.remove('has-photo');preview.classList.add('no-photo');},{once:true});img.src=photo;}}}
  async function openCurrentProductCard(){const d=currentProductPreview;if(!d)return;if(d.product_id&&typeof openWbProduct==='function'){await openWbProduct(d.product_id);return;}const search=String(d.article||d.barcode||'').trim();if(!search)return;go('localcatalog');setTimeout(()=>{const input=document.getElementById('r65CatalogSearch');if(!input)return;input.value=search;input.dispatchEvent(new Event('input',{bubbles:true}));input.focus();},60);}
  async function localCatalogSearch(term,limit=100){return api('/warehouse-ui/catalog/local-products?'+new URLSearchParams({client_id:state.clientId,search:String(term||'').trim(),limit:String(limit)}),{timeoutMs:12000});}
  function pvzBarcodeKey(code){return `${state.clientId||''}|${String(code||'').trim()}`;}
  function pvzCacheProduct(row){if(!row||row.found===false||!row.barcode)return row;const key=pvzBarcodeKey(row.barcode);pvzBarcodeCache.set(key,row);if(pvzBarcodeCache.size>1500)pvzBarcodeCache.delete(pvzBarcodeCache.keys().next().value);return row;}
  async function fastBarcodeLookup(code){const value=String(code||'').trim(),key=pvzBarcodeKey(value);if(pvzBarcodeCache.has(key))return {...pvzBarcodeCache.get(key),cache_hit:true};if(pvzBarcodeFlights.has(key))return pvzBarcodeFlights.get(key);const started=performance.now(),flight=api('/pvz/product-lookup-fast?'+new URLSearchParams({client_id:state.clientId,barcode_value:value}),{timeoutMs:2500}).then(d=>{const out={...d,client_elapsed_ms:Math.max(0,Math.round(performance.now()-started))};if(out?.found!==false)pvzCacheProduct(out);return out;}).finally(()=>pvzBarcodeFlights.delete(key));pvzBarcodeFlights.set(key,flight);return flight;}
