  async function fastArticleSearch(term,limit=80){const value=String(term||'').trim(),key=`${state.clientId||''}|${value.toLocaleLowerCase('ru-RU')}`;if(articleSearchCache.has(key))return articleSearchCache.get(key);const d=await api('/pvz/article-search-fast?'+new URLSearchParams({client_id:state.clientId,article:value,limit:String(limit)}),{timeoutMs:3000});articleSearchCache.set(key,d);if(articleSearchCache.size>200)articleSearchCache.delete(articleSearchCache.keys().next().value);return d;}
