  async function fillProduct(form){const before=form.barcode.value.trim(),code=normalizeStorageKeyboardValue(before),layoutFixed=code!==before,status=q('#pvzProductMatch'),seq=++productLookupSeq,isReceive=form.id==='pvzReceiveForm';if(layoutFixed)form.barcode.value=code;if(!code||!state.clientId){if(isReceive)clearProductPreview();return;}if(status&&isReceive){status.className='pvz-full pvz-small';status.textContent='Ищем ШК в локальной базе…';}try{const d=await fastBarcodeLookup(code);if(seq!==productLookupSeq||form.barcode.value.trim()!==code)return;if(d?.found!==false){form.article.value=d.article||form.article.value||'';form.size.value=d.size||form.size.value||'';form.name.value=d.name||form.name.value||'';if(isReceive)renderProductPreview(d);if(status&&isReceive){status.className='pvz-full pvz-small good';const ms=Number(d.client_elapsed_ms??d.elapsed_ms);status.textContent=`Найдено локально: ${d.article||'—'} · ${d.size||'—'}${Number.isFinite(ms)?` · ${ms} мс`:''}${d.cache_hit?' · кэш':''}${layoutFixed?' · раскладка РУ→EN исправлена':''}`;}}else{form.article.value='';form.size.value='';form.name.value='';if(isReceive)clearProductPreview();if(status&&isReceive){status.className='pvz-full pvz-small warn';status.textContent='ШК не найден в локальной Базе товаров. Заполните артикул и размер вручную — после приёмки карточка сохранится в локальной базе.';}form.article.focus();}}catch(err){if(seq!==productLookupSeq)return;if(isReceive)clearProductPreview();if(status&&isReceive){status.className='pvz-full pvz-small bad';status.textContent=err.message||'Не удалось быстро проверить ШК';}} }
