  function renderDefectAccepted(){const host=q('#pvzDefectAcceptedList');if(!host)return;const w=defectWorker().toLocaleLowerCase('ru-RU'),ref=defectReceiptName();const rows=defectAcceptedRows.filter(r=>(!w||String(r.performed_by||'').trim().toLocaleLowerCase('ru-RU')===w)&&(!ref||String(r.reference||'').trim()===ref));if(!w||!ref){host.innerHTML='<div class="pvz-note">Укажите сотрудника и название приёмки брака — здесь появятся принятые позиции.</div>';return;}if(!rows.length){host.innerHTML='<div class="pvz-note">В этой приёмке брака пока нет позиций.</div>';return;}host.innerHTML=`<div class="pvz-table-wrap"><table class="pvz-table"><thead><tr><th>Время</th><th>Сотрудник</th><th>ШК</th><th>Артикул</th><th>Размер</th><th>Короб</th><th>Причина</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.created_at?new Date(r.created_at).toLocaleTimeString('ru-RU'):'—'}</td><td>${esc(r.performed_by||'—')}</td><td>${esc(r.barcode||'—')}</td><td>${esc(r.article||'—')}</td><td>${esc(r.size||'—')}</td><td>${esc(r.container_name||r.container_barcode||'—')}</td><td>${esc(r.defect_reason||'')}</td><td><button type="button" class="mini danger pvz-delete-defect" data-pvz-delete-defect="${esc(r.line_id)}">Удалить</button></td></tr>`).join('')}</tbody></table></div>`;}
  async function loadDefectAccepted(){const host=q('#pvzDefectAcceptedList');if(!host||!state.clientId||!state.warehouseId)return;if(!defectWorker()||!defectReceiptName()){renderDefectAccepted();return;}host.innerHTML='<div class="pvz-note">Загрузка принятого брака…</div>';try{const d=await api('/defect-storage?'+new URLSearchParams(ctx()),{timeoutMs:20000}),rows=[];for(const box of d.boxes||[])for(const line of box.lines||[])rows.push({...line,container_name:line.container_name||box.name||box.barcode||''});for(const line of d.unboxed||[])rows.push(line);rows.sort((a,b)=>new Date(b.created_at||0)-new Date(a.created_at||0));defectAcceptedRows=rows;renderDefectAccepted();}catch(err){host.innerHTML=`<div class="pvz-note bad">${esc(err.message||'Не удалось загрузить принятый брак')}</div>`;}}
